#!/bin/bash
set -euo pipefail

# This is intentionally an XCTest selection only: each security assertion
# remains in the owning reliable-storage suite.
exec swift test --filter 'RecordingPendingStoreTests/(testCreateRootUsesOwnerOnlyPermissions|testDirectChildIsAcceptedButSymlinkAndEscapeAreRejected|testSessionHandleKeepsOriginalDirectoryAfterNameIsReplacedBySymlink|testUnsafeManifestModeIsPreservedAndRecoveredWithoutFollowingIt|testCorruptManifestPreservesSessionsAndRebuildsNeedsAttentionItems)|RecordingSessionPublisherTests/(testIntermediateDestinationSymlinkIsRejectedWithoutWritingOutside|testSymlinkInSessionTreeIsRejectedWithoutFollowingIt|testNonemptyInvalidMediaIsRejected|testMediaValidatorReadsExactOpenedFileAfterPathReplacement|testDigestMismatchKeepsSourceAndRemovesExactOwnedStaging|testExistingOriginalDestinationUsesItemIDSuffixAndPreservesExistingBytes|testLateFallbackCollisionIsRejectedWithoutOverwritingEitherDestination|testReplacementAtFinalRenameIsPreserved|testPostRenameValidationRejectsRecordingSymlinkWithoutReopeningURL)|RecordingPublicationCoordinatorTests/(testOfflineAttemptRetainsSourceAndManualRetryPublishesThenCleansUp|testRelaunchPublishedItemDeliversCompletionAndCleansUp|testSourceReplacementBeforeCleanupIsNeverDeleted)|RecordingDestinationStoreTests/testStaleBookmarkNeedsFolderAccessAndDoesNotFallBackToDownloads'
